import { createClient } from 'npm:@supabase/supabase-js@2';


// ---- inlined from _shared/cors.ts ----
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// ---- inlined from _shared/supabaseAdmin.ts ----
// Service-role client: bypasses RLS entirely. Only ever used inside Edge
// Functions, never exposed to a browser. SUPABASE_URL and
// SUPABASE_SERVICE_ROLE_KEY are auto-injected into every function's
// runtime by Supabase — no manual secret needed for these two.
function getAdminClient() {
  return createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
    auth: { persistSession: false },
  });
}

// Anon-key client scoped to the caller's own JWT, used only to verify who
// is calling (auth.getUser()) — Supabase validates the token server-side.
function getUserClient(authHeader: string) {
  return createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_ANON_KEY')!, {
    global: { headers: { Authorization: authHeader } },
    auth: { persistSession: false },
  });
}

// ---- inlined from _shared/token.ts ----
// Compact signed QR token: base64url(JSON payload) + "." + base64url(HMAC-SHA256 signature).
// Built on Deno's native Web Crypto API — no JWT library needed for a
// single fixed-shape payload. Verified again by the future Phase 2
// approve-redemption function; the DB `status` column (not this
// signature) is what actually enforces single-use.

interface QrTokenPayload {
  tid: string; // redemption_tokens.id
  cid: string; // customer profile id
  bid: string; // business id
  oid: string; // offer id
  per: string; // period, 'YYYY-MM-01'
  iat: number; // issued-at, unix seconds
  exp: number; // expiry, unix seconds
}

// A voucher's lifetime is set by public.issue_voucher() (to the end of the
// reward month); the token's `exp` mirrors it, and the row's status is what
// enforces single use.

function base64url(bytes: Uint8Array): string {
  let binary = '';
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64url(s: string): Uint8Array {
  const padded = s.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(s.length / 4) * 4, '=');
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function hmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify']
  );
}

async function signQrToken(payload: QrTokenPayload, secret: string): Promise<string> {
  const key = await hmacKey(secret);
  const payloadBytes = new TextEncoder().encode(JSON.stringify(payload));
  const signature = new Uint8Array(await crypto.subtle.sign('HMAC', key, payloadBytes));
  return `${base64url(payloadBytes)}.${base64url(signature)}`;
}

// Returns null on any malformed/invalid-signature/expired token — callers
// treat null as "reject", never distinguishing the reason to the client.
async function verifyQrToken(token: string, secret: string): Promise<QrTokenPayload | null> {
  const [payloadPart, sigPart] = token.split('.');
  if (!payloadPart || !sigPart) return null;

  const key = await hmacKey(secret);
  const payloadBytes = fromBase64url(payloadPart);
  const signatureBytes = fromBase64url(sigPart);

  const valid = await crypto.subtle.verify('HMAC', key, signatureBytes, payloadBytes);
  if (!valid) return null;

  let payload: QrTokenPayload;
  try {
    payload = JSON.parse(new TextDecoder().decode(payloadBytes));
  } catch {
    return null;
  }

  if (typeof payload.exp !== 'number' || payload.exp < Math.floor(Date.now() / 1000)) return null;
  return payload;
}

// ---- redeem-offer/index.ts ----
// Issues a customer's voucher for an offer.
//
// All the rules — membership, a complete profile, the offer being approved
// and live, the business being an eligible paying advertiser, and the
// offer's monthly limit — are enforced inside public.issue_voucher()
// (migration 0011), in one transaction under a per-customer/offer lock.
// Asking again while a voucher is live returns the same voucher, so
// repeated taps never mint extra redemptions.
//
// The response carries both the short code staff can type and a signed QR
// token for camera scanning; either is accepted by approve-redemption.




type RedeemErrorCode =
  | 'UNAUTHENTICATED'
  | 'INVALID_REQUEST'
  | 'NOT_SUBSCRIBED'
  | 'PROFILE_INCOMPLETE'
  | 'OFFER_UNAVAILABLE'
  | 'ALREADY_REDEEMED'
  | 'SERVER_ERROR';

// Exceptions raised by issue_voucher(), mapped to client responses.
const ISSUE_ERRORS: Record<string, { status: number; code: RedeemErrorCode; error: string }> = {
  NOT_SUBSCRIBED: { status: 403, code: 'NOT_SUBSCRIBED', error: 'Become a Town Hub member to redeem rewards.' },
  PROFILE_INCOMPLETE: {
    status: 403,
    code: 'PROFILE_INCOMPLETE',
    error: 'Complete your profile (name and phone number) to redeem rewards.',
  },
  OFFER_UNAVAILABLE: { status: 404, code: 'OFFER_UNAVAILABLE', error: 'This offer is no longer available.' },
  ALREADY_REDEEMED: {
    status: 409,
    code: 'ALREADY_REDEEMED',
    error: "You've used this reward the maximum number of times this month. Check back next month!",
  },
};

function errorResponse(status: number, code: RedeemErrorCode, error: string) {
  return new Response(JSON.stringify({ error, code }), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) {
    return errorResponse(401, 'UNAUTHENTICATED', 'Sign in to redeem rewards.');
  }

  const userClient = getUserClient(authHeader);
  const {
    data: { user },
    error: userError,
  } = await userClient.auth.getUser();
  if (userError || !user) {
    return errorResponse(401, 'UNAUTHENTICATED', 'Sign in to redeem rewards.');
  }

  let body: { offerId?: unknown };
  try {
    body = await req.json();
  } catch {
    return errorResponse(400, 'INVALID_REQUEST', 'Invalid request body.');
  }
  const offerId = body.offerId;
  if (typeof offerId !== 'string' || offerId.length === 0) {
    return errorResponse(400, 'INVALID_REQUEST', 'offerId is required.');
  }

  const secret = Deno.env.get('QR_TOKEN_SECRET');
  if (!secret) {
    console.error('QR_TOKEN_SECRET is not set');
    return errorResponse(500, 'SERVER_ERROR', 'Something went wrong. Please try again.');
  }

  const admin = getAdminClient();

  try {
    const { data: tokenRow, error: issueError } = await admin
      .rpc('issue_voucher', { p_customer: user.id, p_offer: offerId })
      .single();

    if (issueError || !tokenRow) {
      const known = Object.keys(ISSUE_ERRORS).find((k) => issueError?.message?.includes(k));
      if (known) {
        const { status, code, error } = ISSUE_ERRORS[known];
        return errorResponse(status, code, error);
      }
      console.error('issue_voucher failed', issueError);
      return errorResponse(500, 'SERVER_ERROR', 'Something went wrong. Please try again.');
    }

    const token = tokenRow as {
      id: string;
      customer_id: string;
      business_id: string;
      offer_id: string;
      period: string;
      status: 'available' | 'used' | 'expired';
      issued_at: string;
      expires_at: string;
      code: string;
      offer_title: string | null;
    };

    const payload: QrTokenPayload = {
      tid: token.id,
      cid: token.customer_id,
      bid: token.business_id,
      oid: token.offer_id,
      per: token.period,
      iat: Math.floor(new Date(token.issued_at).getTime() / 1000),
      exp: Math.floor(new Date(token.expires_at).getTime() / 1000),
    };
    const qrToken = await signQrToken(payload, secret);

    return new Response(
      JSON.stringify({
        tokenId: token.id,
        code: token.code,
        qrToken,
        status: token.status,
        period: token.period,
        issuedAt: token.issued_at,
        expiresAt: token.expires_at,
        offerTitle: token.offer_title,
      }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (err) {
    console.error('redeem-offer unexpected error', err);
    return errorResponse(500, 'SERVER_ERROR', 'Something went wrong. Please try again.');
  }
});
